{
  "lecture": [
    {
      "etiquette": "F40",
      "R1": {
        "valeur": 1,
        "passage": "coût ajusté pour être égal (en réduisant proportionnellement le budget de jetons de réflexion par appel), le nombre de groupes prédictifs distincts (D1) augmente d'au moins 35 %"
      },
      "R2": {
        "valeur": 1,
        "passage": "Mesure par l'oracle (composantes plantées couvertes dans les propositions brutes et dans les retenues, fausses promotions) et relevé du coût total en jetons et dollars par génération"
      },
      "R3": {
        "valeur": 1,
        "passage": "Aucune modification de l'archive servie (aucun masquage)."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "effectuer 6 appels parallèles et indépendants en sessions neuves sans historique par proposeur et par génération, la consigne de chaque appel demandant exactement 1 carte."
      },
      "R6": {
        "valeur": 1,
        "passage": "quelques dizaines de dollars d'appels pour comparer la couverture oracle de 6 appels d'une carte contre 1 appel de 6 cartes à coût égal."
      },
      "R7": {
        "valeur": 1,
        "passage": "Exploite la propriété de réinitialisation de contexte pour éviter l'effondrement sur un bassin d'idées unique lors de la génération autorégressive séquentielle de plusieurs cartes."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F41",
      "R1": {
        "valeur": 1,
        "passage": "à couverture des composantes plantées égale à une composante près (oracle), la règle d'arrêt coûte au moins 25 % de moins par course que six générations fixes"
      },
      "R2": {
        "valeur": 1,
        "passage": "coût en dollars par course, relevé par les relais, et nombre de composantes plantées couvertes, lu par l'oracle une fois après la course"
      },
      "R3": {
        "valeur": 1,
        "passage": "Le juge, les proposeurs et leurs consignes ne changent pas ; aucun agent ne voit l'estimation."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:cout"
      },
      "R5": {
        "valeur": 0,
        "motif": "La règle ne précise pas quoi calculer ni quelle décision prendre lorsque m vaut zéro."
      },
      "R6": {
        "valeur": 0,
        "motif": "Le témoin à même coût moyen est nommé, mais aucun ordre de grandeur du coût de calcul du rejeu ni des courses supplémentaires éventuelles n'est donné."
      },
      "R7": {
        "valeur": 0,
        "motif": "L'estimation des groupes actuellement atteignables ne relie pas l'arrêt à la conservation de la couverture oracle, notamment pour les composantes rendues accessibles par les générations suivantes."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F42",
      "R1": {
        "valeur": 1,
        "passage": "À nombre de tirages frais égal et cartes identiques : le bras stratifié couvre, à l'étage des retenues, au moins 1,5 fois plus de composantes rares que le bras uniforme"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes par strate de masse (rare / globale), aux étages des représentants et des retenues ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "contre le nul contenant l'archive, les lois aveugles et les recombinaisons"
      },
      "R4": {
        "valeur": 1,
        "passage": "sa validité (espérance au plus 1 sous le nul) se tient conditionnellement à chaque jeu de traits et ne dépend donc pas de la loi selon laquelle les traits sont tirés"
      },
      "R5": {
        "valeur": 1,
        "passage": "fixer d'avance, dans l'engagement scellé, l'effectif par strate : n/S épisodes frais par strate, où n est le nombre total actuel de tirages frais"
      },
      "R6": {
        "valeur": 1,
        "passage": "Rejeu des cartes déjà rendues sur mondes engendrés par programme ; quelques heures de calcul local, zéro appel de modèle, zéro dollar."
      },
      "R7": {
        "valeur": 1,
        "passage": "La stratification lève la borne de dilution (d ≤ r(A)·ln 2) sans un tirage de plus."
      },
      "N": {
        "valeur": "aucune"
      }
    },
    {
      "etiquette": "F43",
      "R1": {
        "valeur": 1,
        "passage": "composantes distinctes couvertes à l'étage des propositions brutes est supérieure d'au moins 1 dans le bras à constats, bien qu'il rende six cartes contre 6·K au témoin"
      },
      "R2": {
        "valeur": 1,
        "passage": "Oracle : composantes certifiées couvertes, étages des propositions brutes, des représentants et des retenues ; lois fausses et copies promues."
      },
      "R3": {
        "valeur": 1,
        "passage": "Aucun modèle ne note, ne trie, ni ne filtre les constats. Extraction, gardien, regroupement des doublons, juge inchangés."
      },
      "R4": {
        "valeur": 1,
        "passage": "levier:proposeurs"
      },
      "R5": {
        "valeur": 1,
        "passage": "appels 2 à 7 (sessions neuves, sans historique) = vue habituelle complète + un seul constat (le i-ème, dans l'ordre rendu, sans tri) + consigne d'une carte au gabarit"
      },
      "R6": {
        "valeur": 1,
        "passage": "15 mondes × 4 proposeurs × (7 appels courts + K appels témoin) en génération 1 ; ordre de quelques dizaines de dollars, devis avant feu vert."
      },
      "R7": {
        "valeur": 1,
        "passage": "l'isolement de chacun dans une session qui ne voit pas les autres, supprime la pression de cohérence interne d'un appel unique sans masquer l'archive, sans quota de formes et sans prime de nouveauté"
      },
      "N": {
        "valeur": "aucune"
      }
    }
  ]
}
